export const events=[{id:'ball',name:'月夜の仮面舞踏会',symbol:'☾',desc:'招待状を辿り、舞踏会に潜む影を退けよう。怪盗ノクスとの出会いが待っている。',rewardHero:5,reward:600,difficulty:1},{id:'ship',name:'幽霊船の星時計',symbol:'⌛',desc:'時を止めた船の甲板で、失われた星時計を取り戻そう。',rewardHero:2,reward:800,difficulty:2},{id:'arena',name:'紅蓮の闘技大会',symbol:'⚔',desc:'強敵との連戦を勝ち抜き、戦乙女にあなたの力を示そう。',rewardHero:4,reward:1000,difficulty:3}];
export function initial(){return{version:1,gems:3000,gold:1500,materials:8,pity:0,pulls:0,wins:0,bondUsed:0,chapter:1,inventory:[],completed:[],party:[0,1],chars:{0:{level:1,xp:0,bond:0,weapon:0},1:{level:1,xp:0,bond:0,weapon:0}},claimed:[]}}
export function summon(s,n,rng=Math.random){if(s.gems<n*300)return null;s.gems-=n*300;const out=[];for(let i=0;i<n;i++){s.pity++;s.pulls++;const ssr=s.pity>=30||rng()<.12;const pool=heroes.filter(h=>h.rarity===(ssr?'SSR':'SR'));const h=pool[Math.min(pool.length-1,Math.floor(rng()*pool.length))];if(ssr)s.pity=0;const duplicate=!!s.chars[h.id];if(duplicate)s.materials+=3;else s.chars[h.id]={level:1,xp:0,bond:0,weapon:0};out.push({hero:h,duplicate})}return out}
export function xpNeeded(c){return c.level*65}export function addXp(s,id,amount){const c=s.chars[id];if(!c)return 0;c.xp+=amount;let levels=0;while(c.xp>=xpNeeded(c)&&c.level<50){c.xp-=xpNeeded(c);c.level++;levels++;s.materials+=2;s.gems+=60;s.inventory.push({name:c.level%5===0?'月光の剣':'月の欠片',level:c.level})}c.bond+=10;return levels}
export function upgrade(s,id){const c=s.chars[id];if(!c||s.materials<2||s.gold<150)return false;s.materials-=2;s.gold-=150;c.weapon++;return true}
export function power(s,id){const c=s.chars[id];return 20+c.level*5+c.weapon*6}
export function bondName(a,b){const els=[a.element,b.element];if(els.includes('ice')&&els.includes('fire'))return '蒼炎の共鳴 — 蒸気爆発';if(els.includes('time'))return '星時計の誓い — 未来からの追撃';if(els.includes('nature'))return '生命の輪舞 — 月光の祝福';if(els.includes('shadow'))return '宵闇の契約 — 幻影乱舞';return '月影の絆 — 双星の一閃'}
export function win(s,eventId){const event=events.find(e=>e.id===eventId);const gems=event?event.reward:180,gold=event?600:280,xp=event?110:80;s.wins++;s.gems+=gems;s.gold+=gold;const leveled=s.party.map(id=>({id,levels:addXp(s,id,xp)}));s.inventory.push({name:'守護者の銀剣',level:s.chapter});s.materials+=3;let unlocked=null;if(event&&!s.completed.includes(event.id)){s.completed.push(event.id);if(!s.chars[event.rewardHero]){s.chars[event.rewardHero]={level:1,xp:0,bond:0,weapon:0};unlocked=event.rewardHero}}if(!event)s.chapter=Math.min(s.chapter+1,10);return{gems,gold,xp,leveled,unlocked}}
